// AI: below section was generated by an AI
// Embed the dashboard and publish model images separately for LittleFS installation.
import { build } from "esbuild";
import { buildEffectPreview, embedEffectPreview, effectScriptTag } from "./build_effects.mjs";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { gzipSync } from "node:zlib";
import { readModels } from "./build_models.mjs";
import { fileURLToPath } from "node:url";
import { minify } from "html-minifier-terser";
import { format } from "prettier";
const directory = new URL("./", import.meta.url);
const bundle = await build({
	entryPoints: [fileURLToPath(new URL("web/app.js", directory))],
	bundle: true,
	minify: true,
	write: false,
	target: "es2020",
	legalComments: "inline",
});
const models = await readModels();
const template = await readFile(new URL("web/dashboard.html", directory), "utf8");
const engine = await buildEffectPreview();
let combined = template.replace(
	"/* INTER_COMMS_BRIDGE */",
	bundle.outputFiles[0].text.replaceAll("</script", "<\\/script"),
);
for (const model of models)
	combined = combined.replaceAll(
		JSON.stringify(model.file),
		'(location.protocol === "file:" ? ' +
			JSON.stringify("web/" + model.file) +
			" : " +
			JSON.stringify(model.path) +
			")",
	);
const html = await minify(combined.replace(effectScriptTag, ""), {
	collapseWhitespace: true,
	removeComments: true,
	minifyCSS: true,
	minifyJS: true,
});
const bytes = gzipSync(html, { level: 9 });
const modelBytes = models.reduce((sum, model) => sum + model.image.length, 0);
if (bytes.length > 64 * 1024) throw new Error("Dashboard exceeds its 64 KiB compressed firmware budget.");
if (modelBytes > 1024 * 1024) throw new Error("Model images exceed their 1 MiB filesystem budget.");
const assets = new URL("../../build_output/inter-comms-assets/", directory);
await mkdir(new URL("inter_comms/", assets), { recursive: true });
for (const model of models) await writeFile(new URL("." + model.path, assets), model.image);
await writeFile(
	new URL("manifest.json", assets),
	JSON.stringify(
		models.map(({ file, path, sha256, image }) => ({
			file,
			path,
			sha256,
			size: image.length,
		})),
		null,
		2,
	) + "\n",
);
// Keep the inspectable dashboard readable; only the embedded firmware asset is minified.
await writeFile(
	new URL("dashboard.html", directory),
	await format(embedEffectPreview(combined, engine), { parser: "html", useTabs: true, tabWidth: 2, printWidth: 120 }),
);
// Only the small HTML page and model manifest occupy the application partition.
function flashArray(name, data) {
	const lines = [];
	for (let i = 0; i < data.length; i += 24)
		lines.push("  " + [...data.subarray(i, i + 24)].map((byte) => "0x" + byte.toString(16).padStart(2, "0")).join(","));
	return "static const uint8_t " + name + "[] PROGMEM = {\n" + lines.join(",\n") + "\n};\n";
}
await writeFile(
	new URL("dashboard_generated.h", directory),
	"// Generated by build_ui.mjs; do not edit.\n#pragma once\n" +
		flashArray("INTER_COMMS_DASHBOARD", bytes) +
		"struct InterCommsModelAsset { const char* path; const char* sha256; size_t size; };\n" +
		"static const InterCommsModelAsset INTER_COMMS_MODELS[] = {\n" +
		models
			.map(
				(model) =>
					"  {" + JSON.stringify(model.path) + ", " + JSON.stringify(model.sha256) + ", " + model.image.length + "} ",
			)
			.join(",\n") +
		"\n};\n",
);
console.log(
	"Dashboard: " +
		bytes.length +
		" compressed firmware HTML bytes; " +
		modelBytes +
		" model bytes packaged for LittleFS",
);
// AI: end
